	/**
	 * Categorize an item. Priority: manual override > ID map > keywords > regex > catch-all.
	 */
	public ItemCategory categorize(String itemName, int itemId)
	{
		// Priority 0: Manual override
		ItemCategory override = manualOverrides.get(itemId);
		if (override != null)
		{
			return override;
		}

		// Priority 1: Hardcoded item ID
		ItemCategory idMatch = itemIdMap.get(itemId);
		if (idMatch != null)
		{
			return idMatch;
		}

		String lowerName = itemName.toLowerCase();

		// Priority 2: Skilling outfits (before generic keywords, so "gloves"/"boots" don't win)
		for (String keyword : SKILLING_OUTFIT_KEYWORDS)
		{
			if (lowerName.contains(keyword))
			{
				return ItemCategory.SKILLING;
			}
		}

		// Priority 2b: Materials rules — before generic keywords, otherwise "Potato seed" hits the Food
		// keyword "potato", "Hammerstone seed" hits "hammer", "Green dragonhide" hits "d'hide", etc.
		if (isFarmingHerbloreMaterial(lowerName) || isMaterialByRule(lowerName))
		{
			return ItemCategory.RAW_MATERIALS;
		}

		// Priority 2c: Adamant / mithril equipment -> High Alch (bolts and arrows stay gear)
		if (isHighAlchByRule(lowerName))
		{
			return ItemCategory.HIGH_ALCH;
		}

		// Priority 2d: small name rules
		for (String kw : GEAR_NAME_RULES) if (lowerName.contains(kw)) return ItemCategory.GEAR;
		for (String kw : SKILLING_NAME_RULES) if (lowerName.contains(kw)) return ItemCategory.SKILLING;
		for (String kw : FOOD_NAME_RULES) if (lowerName.contains(kw)) return ItemCategory.FOOD;
		if (!lowerName.contains("scroll"))
		{
			for (String kw : TELEPORT_NAME_RULES) if (lowerName.contains(kw)) return ItemCategory.TELEPORTS;
		}
		for (String kw : CURRENCY_NAME_RULES) if (lowerName.contains(kw)) return ItemCategory.CURRENCY;

		boolean statsKnown = statsProvider != null && statsReady.getAsBoolean();
		net.runelite.client.game.ItemEquipmentStats stats = statsKnown ? statsProvider.apply(itemId) : null;

		// Priority 3: Keyword matching
		for (ItemCategory category : ItemCategory.values())
		{
			if (category == ItemCategory.QUEST_MISC)
			{
				continue;
			}
			// If we know the item is not equipable, GEAR keywords like "bolt", "ring", "hat"
			// are false positives (Bolt of linen, Ring mould, Chef's hat...) — skip them.
			if (category == ItemCategory.GEAR && statsKnown && stats == null)
			{
				continue;
			}
			for (String keyword : category.getKeywords())
			{
				if (lowerName.contains(keyword.toLowerCase()))
				{
					return category;
				}
			}
		}

		// Priority 4: User-defined regex
		for (Map.Entry<ItemCategory, Pattern> entry : regexPatternCache.entrySet())
		{
			if (entry.getValue().matcher(lowerName).find())
			{
				return entry.getKey();
			}
		}

		// Priority 5: Anything equipable with real combat stats is gear
		// (catches Bandos chestplate, Twisted bow, etc. that no keyword covers)
		if (stats != null && hasCombatStats(stats))
		{
			return ItemCategory.GEAR;
		}

		return ItemCategory.QUEST_MISC;
	}

	/** Seeds, saplings, spores, grimy/clean herbs, unf potions and common secondaries. */
	public static boolean isFarmingHerbloreMaterial(String lowerName)
	{
		if (MATERIAL_NAMES.contains(lowerName)) return true;
		for (String suffix : MATERIAL_SUFFIXES)
		{
			if (lowerName.endsWith(suffix)) return true;
		}
		for (String prefix : MATERIAL_PREFIXES)
		{
			if (lowerName.startsWith(prefix)) return true;
		}
		return false;
	}

	/** Uncut gems, ammo tips, ores, raw food, pastes, bird houses, logs, strings, flax, hides, roots, planks... */
	public static boolean isMaterialByRule(String lowerName)
	{
		for (String x : MATERIAL_RULE_EXACT) if (lowerName.equals(x)) return true;
		// anything compost (bottomless bucket is a Skilling tool; compost potion is a potion)
		if (lowerName.contains("compost") && !lowerName.contains("bottomless") && !lowerName.contains("potion")) return true;
		// "Onyx bolts" (unenchanted) yes; "Onyx bolts (e)" / "Onyx dragon bolts (e)" no
		if (lowerName.endsWith(" bolts") || lowerName.endsWith(" bolts (unf)"))
		{
			for (String b : UNENCHANTED_GEM_BOLTS) if (lowerName.equals(b) || lowerName.endsWith(" " + b)) return true;
		}
		for (String p : MATERIAL_RULE_PREFIXES) if (lowerName.startsWith(p)) return true;
		for (String c : MATERIAL_RULE_CONTAINS) if (lowerName.contains(c)) return true;
		for (String suf : MATERIAL_RULE_SUFFIXES) if (lowerName.endsWith(suf)) return true;
		return false;
	}

	/** Adamant / mithril items other than bolts and arrows (and raw ore/bars, which are materials). */
	public static boolean isHighAlchByRule(String lowerName)
	{
		boolean prefixed = false;
		for (String p : HIGH_ALCH_PREFIXES) if (lowerName.startsWith(p)) prefixed = true;
		if (!prefixed) return false;
		for (String x : HIGH_ALCH_EXCLUDE) if (lowerName.contains(x)) return false;
		return true;
	}

	private static boolean hasCombatStats(net.runelite.client.game.ItemEquipmentStats s)
	{
		return s.getAstab() != 0 || s.getAslash() != 0 || s.getAcrush() != 0
			|| s.getAmagic() != 0 || s.getArange() != 0
			|| s.getDstab() != 0 || s.getDslash() != 0 || s.getDcrush() != 0
			|| s.getDmagic() != 0 || s.getDrange() != 0
			|| s.getStr() != 0 || s.getRstr() != 0 || s.getMdmg() != 0 || s.getPrayer() != 0;
	}

	/**
	 * Provide a lookup for equipment stats by item ID (typically ItemManager-backed).
	 * Optional; without it categorize() falls back to name/ID matching only.
	 */
	public void setStatsProvider(java.util.function.IntFunction<net.runelite.client.game.ItemEquipmentStats> provider)
	{
		setStatsProvider(provider, () -> true);
	}

	/**
	 * @param provider equipment stats lookup by item ID
	 * @param ready    returns false while the stats source hasn't loaded yet; while false the
	 *                 categorizer ignores stats entirely instead of treating every item as non-equipable
	 */
	public void setStatsProvider(java.util.function.IntFunction<net.runelite.client.game.ItemEquipmentStats> provider,
		java.util.function.BooleanSupplier ready)
	{
		this.statsProvider = provider;
		this.statsReady = ready != null ? ready : () -> true;
	}

	/**
	 * Determine the gear sub-category using equipment stats.
	 * Falls back to keyword matching if stats unavailable.
	 */
	// Best-in-slot mega-rares pinned to the top of their style's weapons: scythe (melee), tbow (ranged), shadow (mage)
	private static final String[] PINNED_GEAR = { "scythe of vitur", "twisted bow", "tumeken's shadow" };
	private static final GearSubCategory[] PINNED_GEAR_SUB = {
		GearSubCategory.MELEE_WEAPON, GearSubCategory.RANGED_WEAPON, GearSubCategory.MAGE_WEAPON
	};

	/** Index into PINNED_GEAR for items pinned to the top of their style group, or -1. */
	public static int getPinnedGearRank(String lowerName)
	{
		for (int i = 0; i < PINNED_GEAR.length; i++)
		{
			if (lowerName.contains(PINNED_GEAR[i])) return i;
		}
		return -1;
	}

	public GearSubCategory getGearSubCategory(String itemName, int itemId,
		net.runelite.client.game.ItemEquipmentStats stats)
	{
		// Check ID map first
		GearSubCategory idSub = gearSubIdMap.get(itemId);
		if (idSub != null)
		{
			return idSub;
		}

		// Name rules that stats get wrong (or that must not depend on stats being loaded)
		String lower = itemName.toLowerCase();
		if (lower.contains("twinflame staff")) return GearSubCategory.MAGE_WEAPON;
		int pin = getPinnedGearRank(lower);
		if (pin >= 0) return PINNED_GEAR_SUB[pin];

		// Use equipment stats if available
		if (stats != null)
		{
			return classifyByStats(stats);
		}

		// Fallback to keywords
		return classifyByKeywords(itemName);
	}

	/**
	 * Overload without stats for backwards compatibility.
	 */
	public GearSubCategory getGearSubCategory(String itemName, int itemId)
	{
		return getGearSubCategory(itemName, itemId, null);
	}

	private GearSubCategory classifyByStats(net.runelite.client.game.ItemEquipmentStats stats)
	{
		int meleeAttack = Math.max(stats.getAstab(), Math.max(stats.getAslash(), stats.getAcrush()));
		int rangedAttack = stats.getArange();
		int magicAttack = stats.getAmagic();
		int meleeStr = stats.getStr();
		int rangedStr = stats.getRstr();
		int magicDmg = (int) stats.getMdmg();
		int slot = stats.getSlot();

		// Weapon slots: 3 (weapon), also check two-handed
		boolean isWeapon = (slot == 3) || stats.isTwoHanded();

		// Magic damage % > 0 is always mage
		if (magicDmg > 0)
		{
			return isWeapon ? GearSubCategory.MAGE_WEAPON : GearSubCategory.MAGE_ARMOR;
		}

		// Determine dominant style by attack bonuses
		if (isWeapon)
		{
			if (rangedAttack > meleeAttack && rangedAttack > magicAttack)
			{
				return GearSubCategory.RANGED_WEAPON;
			}
			if (magicAttack > meleeAttack && magicAttack > rangedAttack)
			{
				return GearSubCategory.MAGE_WEAPON;
			}
			if (meleeAttack > 0 || meleeStr > 0)
			{
				return GearSubCategory.MELEE_WEAPON;
			}
			// No clear attack bonus — check strength
			if (rangedStr > 0) return GearSubCategory.RANGED_WEAPON;
			return GearSubCategory.MELEE_WEAPON;
		}
		else
		{
			// Armor: check offensive bonuses to determine style affinity
			if (rangedAttack > 0 && rangedAttack > meleeAttack && rangedAttack > magicAttack)
			{
				return GearSubCategory.RANGED_ARMOR;
			}
			if (magicAttack > 0 && magicAttack > meleeAttack && magicAttack > rangedAttack)
			{
				return GearSubCategory.MAGE_ARMOR;
			}
			if (rangedStr > 0 && rangedStr > meleeStr)
			{
				return GearSubCategory.RANGED_ARMOR;
			}
			if (meleeStr > 0)
			{
				return GearSubCategory.MELEE_ARMOR;
			}

			// Check defensive bonuses as tiebreaker
			int meleeDef = Math.max(stats.getDstab(), Math.max(stats.getDslash(), stats.getDcrush()));
			int rangedDef = stats.getDrange();
			int magicDef = stats.getDmagic();

			// If magic def is negative (typical of melee armor like platebody)
			if (magicDef < 0 && meleeDef > 0)
			{
				return GearSubCategory.MELEE_ARMOR;
			}
			// High magic def with low melee def = mage armor
			if (magicDef > meleeDef && rangedDef < meleeDef)
			{
				return GearSubCategory.MAGE_ARMOR;
			}
			// Ranged armor typically has negative melee def
			if (meleeDef < 0 && rangedDef > 0)
			{
				return GearSubCategory.RANGED_ARMOR;
			}

			return GearSubCategory.GENERAL;
		}
	}

	private GearSubCategory classifyByKeywords(String itemName)
	{
		String lowerName = itemName.toLowerCase();

		for (String kw : MELEE_WEAPON_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.MELEE_WEAPON;
		}
		for (String kw : RANGED_WEAPON_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.RANGED_WEAPON;
		}
		for (String kw : MAGE_WEAPON_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.MAGE_WEAPON;
		}
		for (String kw : MELEE_ARMOR_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.MELEE_ARMOR;
		}
		for (String kw : RANGED_ARMOR_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.RANGED_ARMOR;
		}
		for (String kw : MAGE_ARMOR_KEYWORDS)
		{
			if (lowerName.contains(kw)) return GearSubCategory.MAGE_ARMOR;
		}

		return GearSubCategory.GENERAL;
	}

	/**
	 * Determine the teleport sub-category for an item (only meaningful if category is TELEPORTS).
	 */
	public TeleportSubCategory getTeleportSubCategory(String itemName, int itemId)
	{
		if (RUNE_IDS.contains(itemId))
		{
			return TeleportSubCategory.RUNES;
		}
		if (JEWELRY_IDS.contains(itemId))
		{
			return TeleportSubCategory.JEWELRY;
		}
		if (TABLET_IDS.contains(itemId))
		{
			return TeleportSubCategory.TABLETS;
		}

		// Keyword fallbacks for items not in ID sets
		String lowerName = itemName.toLowerCase();
		if (lowerName.contains("rune"))
		{
			return TeleportSubCategory.RUNES;
		}
		if (lowerName.contains("glory(") || lowerName.contains("dueling(")
			|| lowerName.contains("necklace(") || lowerName.contains("bracelet(")
			|| lowerName.contains("wealth(") || lowerName.contains("passage(")
			|| lowerName.contains("pendant(") || lowerName.contains("amulet(")
			|| lowerName.contains("slayer ring") || lowerName.contains("ring of returning"))
		{
			return TeleportSubCategory.JEWELRY;
		}
		if (lowerName.contains("teleport") && !lowerName.contains("("))
		{
			return TeleportSubCategory.TABLETS;
		}
		if (lowerName.contains("scroll"))
		{
			return TeleportSubCategory.TABLETS;
		}

		return TeleportSubCategory.OTHER;
	}

	/**
	 * Get the sort priority for a gear item given a sort mode.
	 * Lower numbers sort first.
	 */
	// Equipment slot sort order: weapon, head, amulet, cape, body, legs, shield, gloves, boots, ring, ammo
	private static final int[] SLOT_ORDER = new int[14];
	static
	{
		SLOT_ORDER[3] = 0;   // Weapon
		SLOT_ORDER[0] = 1;   // Head
		SLOT_ORDER[2] = 2;   // Amulet/Neck
		SLOT_ORDER[1] = 3;   // Cape
		SLOT_ORDER[4] = 4;   // Body
		SLOT_ORDER[7] = 5;   // Legs
		SLOT_ORDER[5] = 6;   // Shield
		SLOT_ORDER[9] = 7;   // Gloves
		SLOT_ORDER[10] = 8;  // Boots
		SLOT_ORDER[12] = 9;  // Ring
		SLOT_ORDER[13] = 10; // Ammo
	}

	/**
	 * Get a full sort key for a gear item: sub-category, then slot, then stat strength.
	 * Returns a long where higher bits = sub-category, middle bits = slot, lower bits = inverted stat.
	 * Lower values sort first.
	 */
	public long getGearFullSortKey(String itemName, int itemId,
		net.runelite.client.game.ItemEquipmentStats stats, GearSortMode mode)
	{
		GearSubCategory sub = getGearSubCategory(itemName, itemId, stats);
		int subOrder = getGearSortOrder(sub, mode);

		// Pinned mega-rares sit at the top of their style's weapons regardless of stats
		if (getPinnedGearRank(itemName.toLowerCase()) >= 0)
		{
			return ((long) subOrder << 44) | ((long) SLOT_ORDER[3] << 36) | (itemId & 0xFFFF);
		}

		int slotOrder = 0;
		int statValue = 0;

		if (stats != null)
		{
			int slot = stats.getSlot();
			if (slot >= 0 && slot < SLOT_ORDER.length)
			{
				slotOrder = SLOT_ORDER[slot];
			}

			// Get the relevant stat for ordering within slot (highest = first)
			switch (sub)
			{
				case MELEE_WEAPON:
				case MELEE_ARMOR:
					// Melee: strength first, then best accuracy as tiebreaker
					statValue = stats.getStr() * 1000
						+ Math.max(stats.getAstab(), Math.max(stats.getAslash(), stats.getAcrush()));
					break;
				case RANGED_WEAPON:
				case RANGED_ARMOR:
					// Ranged: ranged strength first, then ranged accuracy
					statValue = stats.getRstr() * 1000 + stats.getArange();
					break;
				case MAGE_WEAPON:
				case MAGE_ARMOR:
					// Mage: magic damage first, then magic accuracy
					statValue = (int) stats.getMdmg() * 1000 + stats.getAmagic();
					break;
				default:
					statValue = 0;
			}
		}

		// Invert stat so higher stats sort first (lower key value = sorted first)
		long invertedStat = 999999 - statValue;
		if (invertedStat < 0) invertedStat = 0;

		// Pack into long with enough bits: subOrder (8 bits) | slotOrder (8 bits) | invertedStat (20 bits)
		// Pack: subOrder(8) | slotOrder(8) | invertedStat(20) | itemId(16) for uniqueness
		return ((long) subOrder << 44) | ((long) slotOrder << 36) | ((long)(invertedStat & 0xFFFFF) << 16) | (itemId & 0xFFFF);
	}

	public int getGearSortOrder(GearSubCategory sub, GearSortMode mode)
	{
		if (mode == GearSortMode.COMBAT_STYLE)
		{
			switch (sub)
			{
				case MELEE_WEAPON: return 0;
				case MELEE_ARMOR: return 1;
				case RANGED_WEAPON: return 2;
				case RANGED_ARMOR: return 3;
				case MAGE_WEAPON: return 4;
				case MAGE_ARMOR: return 5;
				case GENERAL: return 6;
				default: return 7;
			}
		}
		else
		{
			// Equipment Type: all weapons by style, then all armor by style
			switch (sub)
			{
				case MELEE_WEAPON: return 0;
				case RANGED_WEAPON: return 1;
				case MAGE_WEAPON: return 2;
				case MELEE_ARMOR: return 3;
				case RANGED_ARMOR: return 4;
				case MAGE_ARMOR: return 5;
				case GENERAL: return 6;
				default: return 7;
			}
		}
	}

	/**
	 * Get the sort priority for a teleport item given a sort mode.
	 */
	// Custom group order for TeleportSortMode.CUSTOM (set from config by the plugin)
	private TeleportSubCategory[] customTeleportOrder = {
		TeleportSubCategory.RUNES, TeleportSubCategory.JEWELRY, TeleportSubCategory.TABLETS, TeleportSubCategory.OTHER
	};

	/** Set the group order used by TeleportSortMode.CUSTOM. Duplicates are ignored, missing groups appended. */
	public void setCustomTeleportOrder(TeleportSubCategory... order)
	{
		java.util.LinkedHashSet<TeleportSubCategory> set = new java.util.LinkedHashSet<>();
		if (order != null) for (TeleportSubCategory t : order) if (t != null) set.add(t);
		for (TeleportSubCategory t : TeleportSubCategory.values()) set.add(t);
		customTeleportOrder = set.toArray(new TeleportSubCategory[0]);
	}

	public TeleportSubCategory[] getTeleportGroupOrder(TeleportSortMode mode)
	{
		switch (mode)
		{
			case JEWELRY_FIRST:
				return new TeleportSubCategory[]{ TeleportSubCategory.JEWELRY, TeleportSubCategory.RUNES, TeleportSubCategory.TABLETS, TeleportSubCategory.OTHER };
			case TABLETS_FIRST:
				return new TeleportSubCategory[]{ TeleportSubCategory.TABLETS, TeleportSubCategory.RUNES, TeleportSubCategory.JEWELRY, TeleportSubCategory.OTHER };
			case TELEPORT_ITEMS_FIRST:
				return new TeleportSubCategory[]{ TeleportSubCategory.OTHER, TeleportSubCategory.RUNES, TeleportSubCategory.JEWELRY, TeleportSubCategory.TABLETS };
			case CUSTOM:
				return customTeleportOrder;
			case RUNES_FIRST:
			default:
				return new TeleportSubCategory[]{ TeleportSubCategory.RUNES, TeleportSubCategory.JEWELRY, TeleportSubCategory.TABLETS, TeleportSubCategory.OTHER };
		}
	}

	public int getTeleportSortOrder(TeleportSubCategory sub, TeleportSortMode mode)
	{
		TeleportSubCategory[] order = getTeleportGroupOrder(mode);
		for (int i = 0; i < order.length; i++)
		{
			if (order[i] == sub) return i;
		}
		return order.length;
	}

	// Rune pouch IDs (all variants)
	private static final Set<Integer> RUNE_POUCH_IDS = new HashSet<>(Arrays.asList(
		12791, 27281 // Rune pouch, Divine rune pouch
	));

	/**
	 * Full sort key for teleport items.
	 * Priority: rune pouch → skill capes → other teleport items → runes/jewelry/tablets
	 */
	public long getTeleportFullSortKey(String itemName, int itemId, TeleportSortMode mode)
	{
		String lower = itemName.toLowerCase();
		boolean runePouch = (RUNE_POUCH_IDS.contains(itemId) || lower.contains("rune pouch")) && !lower.contains("note");

		TeleportSubCategory sub = runePouch ? TeleportSubCategory.RUNES : getTeleportSubCategory(itemName, itemId);
		int groupOrder = getTeleportSortOrder(sub, mode); // 0..3, per sort mode / custom order
		int typeOrder;
		int chargeOrder = 0;

		switch (sub)
		{
			case RUNES:
				// Rune pouches lead the runes group, then elemental > catalytic
				typeOrder = runePouch ? 0 : 1 + getRuneSortOrder(itemId);
				break;
			case JEWELRY:
				typeOrder = getJewelryTypeOrder(itemId, itemName);
				chargeOrder = getChargeOrder(itemName);
				break;
			case TABLETS:
				typeOrder = getTabletOrder(itemName);
				break;
			default: // OTHER: construction cape, farming cape, other skillcapes, other teleport items, crystals last
				if (lower.contains("construct") && (lower.contains("cape") || lower.contains("hood")))
				{
					typeOrder = 0; chargeOrder = lower.contains("(t)") ? 0 : 1;
				}
				else if (lower.contains("farming") && (lower.contains("cape") || lower.contains("hood")))
				{
					typeOrder = 1; chargeOrder = lower.contains("(t)") ? 0 : 1;
				}
				else if ((lower.contains("cape") || lower.contains("hood")) && lower.contains("(t)") || lower.contains("skillcape"))
				{
					typeOrder = 2;
				}
				else if (lower.contains("teleport crystal") || lower.contains("crystal teleport seed") || lower.contains("eternal teleport"))
				{
					typeOrder = 9;
				}
				else
				{
					typeOrder = 3;
				}
				break;
		}

		// group(8) | typeOrder(12) | chargeOrder(8) | itemId(16)
		return ((long) (1 + groupOrder) << 44) | ((long) (typeOrder & 0xFFF) << 24)
			| ((long) (chargeOrder & 0xFF) << 16) | (itemId & 0xFFFF);
	}

	private int getRuneSortOrder(int itemId)
	{
		// Elemental runes first
		switch (itemId)
		{
			case 556: return 0;  // Air rune
			case 555: return 1;  // Water rune
			case 557: return 2;  // Earth rune
			case 554: return 3;  // Fire rune
			// Combination runes
			case 4695: return 10; // Mist rune (air+water) - using placeholder, real IDs may differ
			default: break;
		}
		// Combination runes by name
		// Standard catalytic runes in level order
		switch (itemId)
		{
			case 558: return 20; // Mind rune
			case 559: return 21; // Body rune
			case 564: return 22; // Cosmic rune
			case 562: return 23; // Chaos rune
			case 9075: return 24; // Astral rune
			case 561: return 25; // Nature rune
			case 563: return 26; // Law rune
			case 560: return 27; // Death rune
			case 565: return 28; // Blood rune
			case 566: return 29; // Soul rune
			case 21880: return 30; // Wrath rune
			default: return 50;
		}
	}

	private int getJewelryTypeOrder(int itemId, String itemName)
	{
		String lower = itemName.toLowerCase();
		// Group jewelry by type
		if (lower.contains("ring of dueling")) return 0;
		if (lower.contains("games necklace")) return 1;
		if (lower.contains("ring of wealth")) return 2;
		if (lower.contains("glory")) return 3;
		if (lower.contains("skills necklace")) return 4;
		if (lower.contains("combat bracelet")) return 5;
		if (lower.contains("necklace of passage")) return 6;
		if (lower.contains("burning amulet")) return 7;
		if (lower.contains("digsite pendant")) return 8;
		if (lower.contains("slayer ring")) return 9;
		if (lower.contains("ring of returning")) return 10;
		if (lower.contains("ring of shadows")) return 11;
		return 50;
	}

	private int getChargeOrder(String itemName)
	{
		// Extract charge number from name like "Glory(4)" — higher charges first
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\((\\d+)\\)").matcher(itemName);
		if (m.find())
		{
			int charges = Integer.parseInt(m.group(1));
			return 99 - charges; // Invert so higher charges = lower sort key
		}
		return 100; // Uncharged sorts LAST (after all charged variants)
	}

