@PluginDescriptor(
	name = "Bank Tab Organizer",
	description = "Scans bank items and highlights misplaced ones based on category presets",
	tags = {"bank", "organizer", "sort", "tab", "category"}
)
public class BankOrganizerPlugin extends Plugin
{
	/** Plugin version — keep in sync with build.gradle. Shown in the sidebar and stamped on profiles. */
	public static final String VERSION = "1.1.2";

	private static final Logger log = LoggerFactory.getLogger(BankOrganizerPlugin.class);
	private static final String MENU_SET_PREFIX = "Set: ";
	private static final String MENU_REMOVE_OVERRIDE = "Remove Override";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BankOrganizerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankOrganizerOverlay overlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	private BankOrganizerPanel panel;
	private NavigationButton navButton;
	private ItemCategorizer categorizer;
	private ProfileManager profileManager;

	// Items the user categorized by hand in the active profile (survive defaults re-application)
	private final java.util.Set<Integer> userTouched = new java.util.LinkedHashSet<>();
	private Map<Integer, ItemCategory> misplacedItems = new HashMap<>();
	private Map<Integer, String> misplacedItemNames = new HashMap<>();
	private ItemCategory activeFilter;
	private boolean scanActive = false;
	private boolean categorizeMode = false;
	private boolean subCategoryMode = false;
	private boolean skipUntagged = true;
	private boolean highlightUntagged = false; // Draw boxes on items missing subcategory

	// Ordering state
	private boolean orderingActive = false;
	private List<OrderStep> orderSteps = new ArrayList<>();
	private int currentOrderStep = 0;
	private int lastStepItemId = -1;
	private int stuckCounter = 0;
	private List<Integer> lastSeenItemOrder = new ArrayList<>();
	private boolean previewMode = false;
	private boolean overlayEnabled = false;
	private List<PreviewItem> previewItems = new ArrayList<>();

	public Map<Integer, ItemCategory> getMisplacedItems() { return misplacedItems; }
	public Map<Integer, String> getMisplacedItemNames() { return misplacedItemNames; }
	public ItemCategory getActiveFilter() { return activeFilter; }
	public void setActiveFilter(ItemCategory activeFilter) { this.activeFilter = activeFilter; }
	public boolean isScanActive() { return scanActive; }
	public boolean isCategorizeMode() { return categorizeMode; }
	public void setCategorizeMode(boolean mode) { this.categorizeMode = mode; }
	public boolean isSubCategoryMode() { return subCategoryMode; }
	public void setSubCategoryMode(boolean mode) { this.subCategoryMode = mode; }
	public boolean isSkipUntagged() { return skipUntagged; }
	public void setSkipUntagged(boolean skip) { this.skipUntagged = skip; }
	public boolean isHighlightUntagged() { return highlightUntagged; }
	public void setHighlightUntagged(boolean highlight) { this.highlightUntagged = highlight; }
	public boolean isOrderingActive() { return orderingActive; }
	public List<OrderStep> getOrderSteps() { return orderSteps; }
	public int getCurrentOrderStep() { return currentOrderStep; }
	public ItemCategorizer getCategorizer() { return categorizer; }
	public ItemManager getItemManager() { return itemManager; }
	public BankOrganizerConfig getConfig() { return config; }

	public java.awt.Color getColorForCategory(ItemCategory category)
	{
		switch (category)
		{
			case TELEPORTS: return config.colorTeleports();
			case GEAR: return config.colorCombat();
			case POTIONS: return config.colorPotions();
			case FOOD: return config.colorFood();
			case SKILLING: return config.colorSkilling();
			case RAW_MATERIALS: return config.colorMaterials();
			case HIGH_ALCH: return config.colorHighAlch();
			case CURRENCY: return config.colorCurrency();
			case QUEST_MISC: return config.colorQuestMisc();
			default: return category.getColor();
		}
	}
	public boolean isPreviewMode() { return previewMode; }
	public List<PreviewItem> getPreviewItems() { return previewItems; }
	public boolean isOverlayEnabled() { return overlayEnabled; }
	public void setOverlayEnabled(boolean enabled)
	{
		this.overlayEnabled = enabled;
		if (!enabled)
		{
			// Clear scan state so misplaced boxes don't linger
			scanActive = false;
			misplacedItems.clear();
			misplacedItemNames.clear();
		}
	}

	@Provides
	BankOrganizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankOrganizerConfig.class);
	}

	@Override
	protected void startUp()
	{
		categorizer = new ItemCategorizer();
		// Item stats are fetched asynchronously by RuneLite; use a canary item to tell "not loaded yet"
		// apart from "not equipable" so gear isn't demoted to Misc while stats are still loading.
		categorizer.setStatsProvider(this::getEquipmentStats,
			() -> itemManager.getItemStats(net.runelite.api.ItemID.ABYSSAL_WHIP) != null);
		profileManager = new ProfileManager(config);
		profileManager.loadProfiles();
		updateRegexFromConfig();
		updateTeleportOrderFromConfig();
		loadOverridesFromConfig();
		loadSubOverridesFromConfig();
		userTouched.clear();
		userTouched.addAll(profileManager.getActiveProfile().getUserItems());
		applyDefaultsIfOutdated();

		panel = new BankOrganizerPanel(this);

		// Generate a simple grid icon (represents organized bank)
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D g = icon.createGraphics();
		g.setColor(new java.awt.Color(0, 180, 255));
		// Draw a 3x3 grid of small squares
		for (int r = 0; r < 3; r++)
		{
			for (int c = 0; c < 3; c++)
			{
				g.fillRect(1 + c * 5, 1 + r * 5, 4, 4);
			}
		}
		g.dispose();

		navButton = NavigationButton.builder()
			.tooltip("Bank Tab Organizer")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		if (config.showSidebarIcon())
		{
			clientToolbar.addNavigation(navButton);
		}
		overlayManager.add(overlay);

		log.info("Bank Tab Organizer started!");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		misplacedItems.clear();
		misplacedItemNames.clear();
		scanActive = false;
		categorizeMode = false;
		orderingActive = false;

		log.info("Bank Tab Organizer stopped!");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("bankorganizer".equals(event.getGroup()))
		{
			updateRegexFromConfig();
			updateTeleportOrderFromConfig();

			// Toggle sidebar icon
			if ("showSidebarIcon".equals(event.getKey()))
			{
				if (config.showSidebarIcon())
				{
					clientToolbar.addNavigation(navButton);
				}
				else
				{
					clientToolbar.removeNavigation(navButton);
				}
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!orderingActive || event.getContainerId() != InventoryID.BANK.getId())
		{
			return;
		}

		recomputeOrderSteps();
	}

	@Subscribe
	public void onGameTick(net.runelite.api.events.GameTick event)
	{
		// Poll every tick when ordering is active because rearranging items
		// within a tab doesn't trigger ItemContainerChanged
		if (!orderingActive) return;

		Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
		if (bankWidget == null || bankWidget.isHidden()) return;

		Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankItemContainer == null) return;
		Widget[] children = bankItemContainer.getDynamicChildren();
		if (children == null || children.length == 0) return;

		// Build current item order and compare to last seen
		List<Integer> currentOrder = new ArrayList<>(children.length);
		for (Widget child : children)
		{
			if (child != null && !child.isHidden() && child.getItemId() > 0)
			{
				currentOrder.add(child.getItemId());
			}
		}

		if (!currentOrder.equals(lastSeenItemOrder))
		{
			lastSeenItemOrder = currentOrder;
			recomputeOrderSteps();
		}
	}


	private void recomputeOrderSteps()
	{
		log.debug("Recomputing order steps (bank changed)");
		computeNextOrderStep();
	}

	// === Right-click category assignment ===

	private static final String MENU_CATEGORIZE_ALL = "Categorize tab: ";

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!categorizeMode)
		{
			return;
		}

		// === Check for bank TAB right-click (category mode only, not subcategory) ===
		if (!subCategoryMode)
		{
			Widget tabContainer = client.getWidget(ComponentID.BANK_TAB_CONTAINER);
			if (tabContainer != null)
			{
				String option = event.getOption();
				// Bank tabs have options like "View all items" or "Collapse tab"
				// We hook into any right-click on the tab container
				if ("View all items".equals(option) || "Collapse tab".equals(option)
					|| (option != null && option.startsWith("View tab")))
				{
					int widgetId = event.getActionParam1();
					// Add "Categorize tab: X" for each category
					ItemCategory[] categories = ItemCategory.values();
					for (int i = categories.length - 1; i >= 0; i--)
					{
						ItemCategory cat = categories[i];
						String colorTag = ColorUtil.colorTag(getColorForCategory(cat));
						client.createMenuEntry(-1)
							.setOption(colorTag + MENU_CATEGORIZE_ALL + cat.getDisplayName())
							.setTarget(event.getTarget())
							.setIdentifier(event.getIdentifier())
							.setType(MenuAction.RUNELITE)
							.setParam0(event.getActionParam0())
							.setParam1(widgetId);
					}
				}
			}
		}

		// === Check for bank ITEM right-click ===
		Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankItemContainer == null)
		{
			return;
		}

		String option = event.getOption();
		if (!"Examine".equals(option))
		{
			return;
		}

		int widgetId = event.getActionParam1();
		if (widgetId != bankItemContainer.getId())
		{
			return;
		}

		// Get actual item ID from the widget child at this slot
		int slot = event.getActionParam0();
		Widget[] children = bankItemContainer.getDynamicChildren();
		if (children == null || slot < 0 || slot >= children.length)
		{
			return;
		}
		Widget child = children[slot];
		if (child == null)
		{
			return;
		}
		int itemId = child.getItemId();
		if (itemId <= 0)
		{
			return;
		}

		// Find the current category for this item
		String itemName = itemManager.getItemComposition(itemId).getName();
		ItemCategory currentCategory = categorizer.categorize(
			itemName != null ? itemName : "", itemId);

		// Get current subcategory — context-aware based on category
		String[] subNames;
		java.awt.Color[] subColors;
		int currentSubIdx;
		String currentSubName;

		if (currentCategory == ItemCategory.RAW_MATERIALS)
		{
			subNames = ItemCategorizer.SKILL_NAMES;
			subColors = ItemCategorizer.SKILL_COLORS; // Reuse skill colors
			currentSubIdx = categorizer.getMaterialGroupIndex(
				itemName != null ? itemName : "", itemId);
			currentSubName = (currentSubIdx < subNames.length) ? subNames[currentSubIdx] : null;
		}
		else
		{
			subNames = ItemCategorizer.SKILL_NAMES;
			subColors = ItemCategorizer.SKILL_COLORS;
			currentSubIdx = categorizer.getSkillGroupIndex(
				itemName != null ? itemName : "", itemId);
			currentSubName = (currentSubIdx < subNames.length) ? subNames[currentSubIdx] : null;
		}

		// Add "Remove: {sub}" if has subcategory override, or "Remove Override" for category
		if (categorizer.hasSubCategoryOverride(itemId))
		{
			int subIdx = categorizer.getSubCategoryOverrides().get(itemId);
			String subName = subIdx < subNames.length ? subNames[subIdx] : "Unknown";
			java.awt.Color subColor = subIdx < subColors.length
				? subColors[subIdx] : getColorForCategory(currentCategory);
			client.createMenuEntry(-1)
				.setOption(ColorUtil.colorTag(subColor) + "Remove: " + subName)
				.setTarget(event.getTarget())
				.setIdentifier(itemId)
				.setType(MenuAction.RUNELITE)
				.setParam0(event.getActionParam0())
				.setParam1(widgetId);
		}
		else if (categorizer.hasManualOverride(itemId))
		{
			client.createMenuEntry(-1)
				.setOption(MENU_REMOVE_OVERRIDE)
				.setTarget(event.getTarget())
				.setIdentifier(itemId)
				.setType(MenuAction.RUNELITE)
				.setParam0(event.getActionParam0())
				.setParam1(widgetId);
		}

		if (subCategoryMode)
		{
			// SUBCATEGORY MODE: show subcategories for this item's category type
			for (int i = subNames.length - 1; i >= 0; i--)
			{
				java.awt.Color color = i < subColors.length
						? subColors[i] : getColorForCategory(currentCategory);

				String prefix = (currentSubName != null && subNames[i].equals(currentSubName))
					? "Current: " : "Sub: ";

				client.createMenuEntry(-1)
					.setOption(ColorUtil.colorTag(color)
						+ prefix + subNames[i])
					.setTarget(event.getTarget())
					.setIdentifier(itemId)
					.setType(MenuAction.RUNELITE)
					.setParam0(event.getActionParam0())
					.setParam1(widgetId);
			}
		}
		else
		{
			// CATEGORY MODE: show all categories
			ItemCategory[] categories = ItemCategory.values();
			for (int i = categories.length - 1; i >= 0; i--)
			{
				ItemCategory cat = categories[i];
				String colorTag = ColorUtil.colorTag(getColorForCategory(cat));

				if (cat == currentCategory)
				{
					client.createMenuEntry(-1)
						.setOption(colorTag + "Current: " + cat.getDisplayName())
						.setTarget(event.getTarget())
						.setIdentifier(itemId)
						.setType(MenuAction.RUNELITE)
						.setParam0(event.getActionParam0())
						.setParam1(widgetId);
				}
				else
				{
					client.createMenuEntry(-1)
						.setOption(colorTag + MENU_SET_PREFIX + cat.getDisplayName())
						.setTarget(event.getTarget())
						.setIdentifier(itemId)
					.setType(MenuAction.RUNELITE)
					.setParam0(event.getActionParam0())
					.setParam1(widgetId);
			}
		}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!categorizeMode)
		{
			return;
		}

		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}

		// Strip color tags for comparison
		String stripped = option.replaceAll("<[^>]+>", "");

		// Handle "Categorize tab: X" — mass-categorize all visible items
		if (stripped.startsWith(MENU_CATEGORIZE_ALL))
		{
			String categoryName = stripped.substring(MENU_CATEGORIZE_ALL.length());
			for (ItemCategory cat : ItemCategory.values())
			{
				if (cat.getDisplayName().equals(categoryName))
				{
					categorizeAllVisibleItems(cat);
					break;
				}
			}
			return;
		}

		if (MENU_REMOVE_OVERRIDE.equals(stripped) || stripped.startsWith("Remove: "))
		{
			int itemId = event.getId();
			categorizer.removeManualOverride(itemId);
			categorizer.removeSubCategoryOverride(itemId);
			userTouched.add(itemId);
			saveOverridesToConfig();
			saveSubOverridesToConfig();
			log.info("Removed overrides for item ID {}", itemId);
			// Update overlay immediately: remove from misplaced or re-categorize
			String name = misplacedItemNames.get(itemId);
			if (name != null)
			{
				ItemCategory newCat = categorizer.categorize(name, itemId);
				int currentTab = client.getVarbitValue(4150);
				ItemCategory expectedCat = getCategoryForTab(currentTab);
				if (expectedCat != null && newCat == expectedCat)
				{
					misplacedItems.remove(itemId);
					misplacedItemNames.remove(itemId);
				}
				else
				{
					misplacedItems.put(itemId, newCat);
				}
			}
			refreshPanel();
			return;
		}

		if (stripped.startsWith(MENU_SET_PREFIX))
		{
			String categoryName = stripped.substring(MENU_SET_PREFIX.length());
			int itemId = event.getId();
			log.info("Category click: itemId={}, category={}", itemId, categoryName);

			for (ItemCategory cat : ItemCategory.values())
			{
				if (cat.getDisplayName().equals(categoryName))
				{
					categorizer.setManualOverride(itemId, cat);
					userTouched.add(itemId);
					saveOverridesToConfig();
					log.info("Set item ID {} to category {}", itemId, cat);
					// Update overlay immediately
					int currentTab = client.getVarbitValue(4150);
					ItemCategory expectedCat = getCategoryForTab(currentTab);
					String itemName = itemManager.getItemComposition(itemId).getName();
					if (expectedCat != null && cat == expectedCat)
					{
						misplacedItems.remove(itemId);
						misplacedItemNames.remove(itemId);
					}
					else
					{
						misplacedItems.put(itemId, cat);
						misplacedItemNames.put(itemId, itemName != null ? itemName : "Unknown");
						scanActive = true;
					}
					refreshPanel();
					break;
				}
			}
		}

		// Handle subcategory assignment — check both skill names and material group names
		if (stripped.startsWith("Sub: "))
		{
			String subName = stripped.substring(5);
			int itemId = event.getId();
			boolean found = false;

			// Check skill names first
			for (int i = 0; i < ItemCategorizer.SKILL_NAMES.length; i++)
			{
				if (ItemCategorizer.SKILL_NAMES[i].equals(subName))
				{
					categorizer.setSubCategoryOverride(itemId, i);
					userTouched.add(itemId);
					saveSubOverridesToConfig();
					log.info("Set item ID {} to subcategory {} ({})", itemId, i, subName);
					found = true;
					break;
				}
			}

			// Then check material group names
			if (!found)
			{
				for (int i = 0; i < ItemCategorizer.SKILL_NAMES.length; i++)
				{
					if (ItemCategorizer.SKILL_NAMES[i].equals(subName))
					{
						categorizer.setSubCategoryOverride(itemId, i);
					userTouched.add(itemId);
						saveSubOverridesToConfig();
						log.info("Set item ID {} to material subcategory {} ({})", itemId, i, subName);
						break;
					}
				}
			}
		}
	}

	// === Override persistence ===

	private void loadOverridesFromConfig()
	{
		String json = config.manualOverrides();
		if (json == null || json.isEmpty())
		{
			// Load defaults from resource file for new users
			json = loadResourceFile("default_overrides.txt");
			if (json != null && !json.isEmpty())
			{
				config.setManualOverrides(json);
				log.info("Loaded default category overrides");
			}
			else
			{
				return;
			}
		}

		categorizer.loadManualOverrides(ItemCategorizer.parseCategoryOverrides(json));
	}

	private void saveOverridesToConfig()
	{
		Map<Integer, ItemCategory> overrides = categorizer.getManualOverrides();
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, ItemCategory> entry : overrides.entrySet())
		{
			if (sb.length() > 0) sb.append(",");
			sb.append(entry.getKey()).append(":").append(entry.getValue().name());
		}
		config.setManualOverrides(sb.toString());
	}

	private void loadSubOverridesFromConfig()
	{
		String json = config.subCategoryOverrides();
		if (json == null || json.isEmpty())
		{
			json = loadResourceFile("default_sub_overrides.txt");
			if (json != null && !json.isEmpty())
			{
				config.setSubCategoryOverrides(json);
				log.info("Loaded default subcategory overrides");
			}
			else
			{
				return;
			}
		}

		categorizer.loadSubCategoryOverrides(ItemCategorizer.parseSubCategoryOverrides(json));
	}

	private void saveSubOverridesToConfig()
	{
