	private void categorizeAllVisibleItems(ItemCategory category)
	{
		Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankItemContainer == null) return;
		Widget[] children = bankItemContainer.getDynamicChildren();
		if (children == null) return;

		int currentTab = getCurrentBankTab();
		int count = 0;
		for (int slot = 0; slot < children.length; slot++)
		{
			Widget child = children[slot];
			if (child == null || child.isHidden() || !isSlotInTab(currentTab, slot)) continue;
			int itemId = child.getItemId();
			if (itemId <= 0) continue;

			categorizer.setManualOverride(itemId, category);
			userTouched.add(itemId);
			count++;
		}

		saveOverridesToConfig();
		log.info("Categorized {} items as {}", count, category.getDisplayName());

		final int total = count;
		javax.swing.JOptionPane.showMessageDialog(null,
			"Set " + total + " items to " + category.getDisplayName(),
			"Categorize Tab",
			javax.swing.JOptionPane.INFORMATION_MESSAGE);
	}

	private String loadResourceFile(String filename)
	{
		try (java.io.InputStream is = getClass().getResourceAsStream("/com/bankorganizer/" + filename))
		{
			if (is == null) return null;
			return new String(is.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).trim();
		}
		catch (Exception e)
		{
			log.error("Failed to load resource {}", filename, e);
			return null;
		}
	}

