	public ItemCategory getCategoryForTab(int tabNumber)
	{
		switch (tabNumber)
		{
			case 0: return config.tab0Category();
			case 1: return config.tab1Category();
			case 2: return config.tab2Category();
			case 3: return config.tab3Category();
			case 4: return config.tab4Category();
			case 5: return config.tab5Category();
			case 6: return config.tab6Category();
			case 7: return config.tab7Category();
			case 8: return config.tab8Category();
			case 9: return config.tab9Category();
			default: return null;
		}
	}

	public Map<ItemCategory, Integer> getTabMappings()
	{
		Map<ItemCategory, Integer> mappings = new EnumMap<>(ItemCategory.class);
		for (int i = 1; i <= 9; i++)
		{
			ItemCategory cat = getCategoryForTab(i);
			if (cat != null && !mappings.containsKey(cat))
			{
				mappings.put(cat, i);
			}
		}
		// Main tab (0) only claims a category no numbered tab already has
		ItemCategory mainCat = getCategoryForTab(0);
		if (mainCat != null && !mappings.containsKey(mainCat))
		{
			mappings.put(mainCat, 0);
		}
		return mappings;
	}

	private int getCurrentBankTab()
	{
		return client.getVarbitValue(4150);
	}

	/**
	 * When the "All" view (tab 0) is open the item container holds every item: tabs 1-9 first, then
	 * the un-tabbed "main tab" items. Returns the first slot of that main-tab section.
	 */
	private int getMainTabFirstSlot()
	{
		int sum = 0;
		for (int varbit = net.runelite.api.Varbits.BANK_TAB_ONE_COUNT; varbit <= net.runelite.api.Varbits.BANK_TAB_NINE_COUNT; varbit++)
		{
			sum += client.getVarbitValue(varbit);
		}
		return sum;
	}

	/** True if the given container slot belongs to the tab currently being viewed. */
	private boolean isSlotInTab(int currentTab, int slot)
	{
		return currentTab != 0 || slot >= getMainTabFirstSlot();
	}

	// === Scan ===

	public void scanCurrentTab()
	{
		clientThread.invokeLater(() ->
		{
			Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
			if (bankWidget == null || bankWidget.isHidden())
			{
				log.debug("Bank is not open");
				return;
			}

			int currentTab = getCurrentBankTab();
			ItemCategory expectedCategory = getCategoryForTab(currentTab);

			Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
			if (bankItemContainer == null)
			{
				return;
			}

			Widget[] children = bankItemContainer.getDynamicChildren();
			if (children == null)
			{
				return;
			}

			Map<Integer, ItemCategory> newMisplaced = new HashMap<>();
			Map<Integer, String> newNames = new HashMap<>();

			for (int slot = 0; slot < children.length; slot++)
			{
				Widget child = children[slot];
				if (child == null || child.isHidden() || !isSlotInTab(currentTab, slot))
				{
					continue;
				}

				int itemId = child.getItemId();
				if (itemId <= 0)
				{
					continue;
				}

				String itemName = itemManager.getItemComposition(itemId).getName();
				if (itemName == null || itemName.equals("null"))
				{
					continue;
				}

				ItemCategory correctCategory = categorizer.categorize(itemName, itemId);
				log.debug("Item: {} (ID: {}) -> {}", itemName, itemId, correctCategory);

				if (expectedCategory != null && correctCategory != expectedCategory)
				{
					newMisplaced.put(itemId, correctCategory);
					newNames.put(itemId, itemName);
				}
				else if (expectedCategory == null)
				{
					newMisplaced.put(itemId, correctCategory);
					newNames.put(itemId, itemName);
				}
			}

			misplacedItems = newMisplaced;
			misplacedItemNames = newNames;
			scanActive = true;

			Map<ItemCategory, Integer> tabMappings = getTabMappings();

			SwingUtilities.invokeLater(() ->
				panel.updateResults(newMisplaced, newNames, tabMappings));

			log.info("Scan complete: {} misplaced items found", newMisplaced.size());
		});
	}

	// === Ordering ===

	public void startOrdering()
	{
		clientThread.invokeLater(() ->
		{
			orderingActive = true;
			computeNextOrderStep();
		});
	}

	/**
	 * Compute the next ordering step using LIS-based optimal algorithm.
	 * Perfect swaps first (2-cycles), then insert non-LIS items front-to-back.
	 * Minimum total actions = (perfect swaps) + (n - LIS_length - 2*swaps).
	 */
	private void computeNextOrderStep()
	{
		Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
		if (bankWidget == null || bankWidget.isHidden()) return;

		int currentTab = client.getVarbitValue(4150);
		ItemCategory tabCategory = getCategoryForTab(currentTab);
		if (tabCategory == null) return;

		Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankItemContainer == null) return;
		Widget[] children = bankItemContainer.getDynamicChildren();
		if (children == null) return;

		// Collect current items (only the main-tab section when viewing "All")
		List<BankItem> currentItems = new ArrayList<>();
		for (int slot = 0; slot < children.length; slot++)
		{
			Widget child = children[slot];
			if (child == null || child.isHidden() || !isSlotInTab(currentTab, slot)) continue;
			int itemId = child.getItemId();
			if (itemId <= 0) continue;
			String name = itemManager.getItemComposition(itemId).getName();
			if (name == null || name.equals("null")) continue;
			currentItems.add(new BankItem(itemId, name, slot));
		}

		int n = currentItems.size();
		if (n == 0) return;

		// Compute ideal order
		GearSortMode gearMode = config.gearSortMode();
		TeleportSortMode teleportMode = config.teleportSortMode();

		List<BankItem> idealOrder = new ArrayList<>(currentItems);
		idealOrder.sort(Comparator.comparingLong(item ->
			getItemSortKey(item, tabCategory, gearMode, teleportMode)
		));

		// Build permutation: perm[i] = ideal position of item currently at position i
		Map<Integer, Integer> idealPosMap = new HashMap<>();
		for (int i = 0; i < idealOrder.size(); i++)
		{
			idealPosMap.put(idealOrder.get(i).itemId, i);
		}

		int[] perm = new int[n];
		boolean allCorrect = true;
		for (int i = 0; i < n; i++)
		{
			Integer pos = idealPosMap.get(currentItems.get(i).itemId);
			perm[i] = pos != null ? pos : i;
			if (perm[i] != i) allCorrect = false;
		}

		if (allCorrect)
		{
			log.info("All {} items in correct order — ordering complete", n);
			orderingActive = false;
			orderSteps.clear();
			currentOrderStep = 0;
			SwingUtilities.invokeLater(() ->
			{
				panel.updateOrderingState();
				javax.swing.JOptionPane.showMessageDialog(null,
					"All items are now in order!",
					"Ordering Complete",
					javax.swing.JOptionPane.INFORMATION_MESSAGE);
			});
			return;
		}

		OrderStep nextStep = null;

		// Simple front-to-back: find first wrong position and insert correct item
		// This builds a sorted prefix that never gets disturbed by subsequent inserts
		{
			for (int idealPos = 0; idealPos < n; idealPos++)
			{
				BankItem idealItem = idealOrder.get(idealPos);

				// Skip if already in correct position
				if (idealPos < currentItems.size()
					&& currentItems.get(idealPos).itemId == idealItem.itemId)
				{
					continue;
				}

				// Log the mismatch for debugging
				if (idealPos < currentItems.size())
				{
					log.debug("Pos {}: expected {} (ID:{}), got {} (ID:{})",
						idealPos, idealItem.name, idealItem.itemId,
						currentItems.get(idealPos).name, currentItems.get(idealPos).itemId);
				}

				// Skip items without subcategory (group 99)
				if (tabCategory == ItemCategory.SKILLING)
				{
					int skillIdx = categorizer.getSkillGroupIndex(idealItem.name, idealItem.itemId);
					if (skillIdx >= 99) continue;
				}
				else if (tabCategory == ItemCategory.RAW_MATERIALS)
				{
					int grpIdx = categorizer.getMaterialGroupIndex(idealItem.name, idealItem.itemId);
					if (grpIdx >= 99) continue;
				}

				BankItem currentAtTarget = currentItems.get(idealPos);
				String subCatName = getSubCategoryName(idealItem, tabCategory);

				// Build phase description
				String phase = "Sorting";
				if (tabCategory == ItemCategory.SKILLING)
				{
					int skillIdx = categorizer.getSkillGroupIndex(idealItem.name, idealItem.itemId);
					if (skillIdx < ItemCategorizer.SKILL_NAMES.length)
					{
						phase = "Grouping " + ItemCategorizer.SKILL_NAMES[skillIdx] + " items";
					}
				}
				else if (tabCategory == ItemCategory.RAW_MATERIALS)
				{
					int grpIdx = categorizer.getMaterialGroupIndex(idealItem.name, idealItem.itemId);
					if (grpIdx < ItemCategorizer.SKILL_NAMES.length)
					{
						phase = "Grouping " + ItemCategorizer.SKILL_NAMES[grpIdx];
					}
				}
				else if (tabCategory == ItemCategory.GEAR)
				{
				phase = "Grouping " + subCatName;
				}
				else if (tabCategory == ItemCategory.TELEPORTS)
				{
					phase = "Grouping " + subCatName;
				}

				int outOfPlace = 0;
				for (int k = 0; k < n; k++)
				{
					if (perm[k] != k) outOfPlace++;
				}

				nextStep = new OrderStep(
					idealItem.itemId, idealItem.name, idealPos,
					"Insert " + idealItem.name + " before " + currentAtTarget.name,
					subCatName,
					currentAtTarget.itemId,
					phase, outOfPlace
				);
				break;
			}
		}

		if (nextStep != null)
		{
			// Detect stuck loop — same item suggested for 10+ ticks
			if (nextStep.itemId == lastStepItemId)
			{
				stuckCounter++;
				if (stuckCounter > 10)
				{
					// Skip this item and find the next one
					log.warn("Stuck on item {} (ID:{}), skipping", nextStep.itemName, nextStep.itemId);
					// Mark this position as handled by continuing past it
					// Find the NEXT out-of-place item after this one
					OrderStep skippedStep = nextStep;
					nextStep = null;
					for (int pos = skippedStep.targetSlot + 1; pos < n; pos++)
					{
						if (pos < currentItems.size() && pos < idealOrder.size()
							&& currentItems.get(pos).itemId != idealOrder.get(pos).itemId)
						{
							BankItem idealItem = idealOrder.get(pos);
							if (tabCategory == ItemCategory.SKILLING)
							{
								int skillIdx = categorizer.getSkillGroupIndex(idealItem.name, idealItem.itemId);
								if (skillIdx >= 99) continue;
							}
							else if (tabCategory == ItemCategory.RAW_MATERIALS)
							{
								int grpIdx = categorizer.getMaterialGroupIndex(idealItem.name, idealItem.itemId);
								if (grpIdx >= 99) continue;
							}
							BankItem currentAtTarget = currentItems.get(pos);
							nextStep = new OrderStep(
								idealItem.itemId, idealItem.name, pos,
								"Insert " + idealItem.name + " before " + currentAtTarget.name,
								getSubCategoryName(idealItem, tabCategory),
								currentAtTarget.itemId,
								"Sorting", perm[pos] != pos ? 1 : 0
							);
							break;
						}
					}
					stuckCounter = 0;
				}
			}
			else
			{
				lastStepItemId = nextStep.itemId;
				stuckCounter = 0;
			}

			if (nextStep != null)
			{
				List<OrderStep> steps = new ArrayList<>();
				steps.add(nextStep);
				orderSteps = steps;
				currentOrderStep = 0;

				SwingUtilities.invokeLater(() -> panel.updateOrderingState());
				log.info("Ordering: {} items out of place. Next: {}",
					nextStep.totalOutOfPlace, nextStep.instruction);
			}
		}
		else
		{
			// No actionable steps found (remaining items are all "everything else")
			// Treat as complete
			int skippedCount = 0;
			for (int i = 0; i < n; i++)
			{
				if (perm[i] != i) skippedCount++;
			}
			final int skipped = skippedCount;
			log.info("Ordering done — {} unsorted items skipped (unknown subcategory)", skipped);
			orderingActive = false;
			orderSteps.clear();
			currentOrderStep = 0;
			SwingUtilities.invokeLater(() ->
			{
				panel.updateOrderingState();
				if (skipped > 0)
				{
					javax.swing.JOptionPane.showMessageDialog(null,
						"Ordering complete! " + skipped + " items with no subcategory were left in place.",
						"Ordering Complete",
						javax.swing.JOptionPane.INFORMATION_MESSAGE);
				}
				else
				{
					javax.swing.JOptionPane.showMessageDialog(null,
						"All items are now in order!",
						"Ordering Complete",
						javax.swing.JOptionPane.INFORMATION_MESSAGE);
				}
			});
		}
	}

	/**
	 * Compute the Longest Increasing Subsequence of a permutation.
	 * Returns the set of INDICES in the input array that form the LIS.
	 * O(n log n) using patience sorting.
	 */
	private Set<Integer> computeLIS(int[] perm)
	{
		int n = perm.length;
		if (n == 0) return new java.util.HashSet<>();

		// tails[k] = smallest ending value of increasing subsequence of length k+1
		List<Integer> tails = new ArrayList<>();
		List<Integer> tailIndices = new ArrayList<>();
		int[] parent = new int[n];
		java.util.Arrays.fill(parent, -1);

		for (int i = 0; i < n; i++)
		{
			int pos = java.util.Collections.binarySearch(tails, perm[i]);
			if (pos < 0) pos = -(pos + 1);

			if (pos == tails.size())
			{
				tails.add(perm[i]);
				tailIndices.add(i);
			}
			else
			{
				tails.set(pos, perm[i]);
				tailIndices.set(pos, i);
			}

			if (pos > 0)
			{
				parent[i] = tailIndices.get(pos - 1);
			}
		}

		// Backtrack to find LIS indices
		Set<Integer> lisIndices = new java.util.HashSet<>();
		int k = tailIndices.get(tails.size() - 1);
		while (k != -1)
		{
			lisIndices.add(k);
			k = parent[k];
		}

		return lisIndices;
	}

	private String getSubCategoryName(BankItem item, ItemCategory tabCategory)
	{
		if (tabCategory == ItemCategory.GEAR)
		{
			return categorizer.getGearSubCategory(item.name, item.itemId,
				getEquipmentStats(item.itemId)).getDisplayName();
		}
		else if (tabCategory == ItemCategory.TELEPORTS)
		{
			return categorizer.getTeleportSubCategory(item.name, item.itemId).getDisplayName();
		}
		else if (tabCategory == ItemCategory.RAW_MATERIALS)
		{
			int idx = categorizer.getMaterialGroupIndex(item.name, item.itemId);
			if (idx < ItemCategorizer.SKILL_NAMES.length)
			{
				return ItemCategorizer.SKILL_NAMES[idx];
			}
		}
		else if (tabCategory == ItemCategory.SKILLING)
		{
			int idx = categorizer.getSkillGroupIndex(item.name, item.itemId);
			if (idx < ItemCategorizer.SKILL_NAMES.length)
			{
				return ItemCategorizer.SKILL_NAMES[idx];
			}
		}
		return "";
	}

	public void advanceOrderStep()
	{
		if (currentOrderStep < orderSteps.size() - 1)
		{
			currentOrderStep++;
			SwingUtilities.invokeLater(() -> panel.updateOrderingState());
		}
		else
		{
			stopOrdering();
		}
	}

	public void stopOrdering()
	{
		orderingActive = false;
		orderSteps.clear();
		currentOrderStep = 0;
		SwingUtilities.invokeLater(() -> panel.updateOrderingState());
	}

	public void togglePreview()
	{
		previewMode = !previewMode;
		if (previewMode)
		{
			computePreview();
		}
		else
		{
			previewItems.clear();
		}
	}

	private void computePreview()
	{
		clientThread.invokeLater(() ->
		{
			Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
			if (bankWidget == null || bankWidget.isHidden()) return;

			int currentTab = client.getVarbitValue(4150);
			ItemCategory tabCategory = getCategoryForTab(currentTab);
			if (tabCategory == null) return;

			Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
			if (bankItemContainer == null) return;
			Widget[] children = bankItemContainer.getDynamicChildren();
			if (children == null) return;

			List<BankItem> items = new ArrayList<>();
			for (int slot = 0; slot < children.length; slot++)
			{
				Widget child = children[slot];
				if (child == null || child.isHidden() || !isSlotInTab(currentTab, slot)) continue;
				int itemId = child.getItemId();
				if (itemId <= 0) continue;
				String name = itemManager.getItemComposition(itemId).getName();
				if (name == null || name.equals("null")) continue;
				items.add(new BankItem(itemId, name, slot));
			}

			GearSortMode gearMode = config.gearSortMode();
			TeleportSortMode teleportMode = config.teleportSortMode();

			List<BankItem> sorted = new ArrayList<>(items);
			sorted.sort(Comparator.comparingLong(item ->
				getItemSortKey(item, tabCategory, gearMode, teleportMode)
			));

			List<PreviewItem> preview = new ArrayList<>();
			for (int i = 0; i < sorted.size(); i++)
			{
				BankItem item = sorted.get(i);
				String subCat = "";
				if (tabCategory == ItemCategory.GEAR)
				{
					subCat = categorizer.getGearSubCategory(item.name, item.itemId,
						getEquipmentStats(item.itemId)).getDisplayName();
				}
				else if (tabCategory == ItemCategory.TELEPORTS)
				{
					subCat = categorizer.getTeleportSubCategory(item.name, item.itemId).getDisplayName();
				}
				preview.add(new PreviewItem(item.itemId, item.name, subCat, i));
			}

			previewItems = preview;
			log.info("Preview computed: {} items", preview.size());
		});
	}

	// === Helper classes ===

	public static class BankItem
	{
		public final int itemId;
		public final String name;
		public final int slot;

		public BankItem(int itemId, String name, int slot)
		{
			this.itemId = itemId;
			this.name = name;
			this.slot = slot;
		}
	}

	public static class OrderStep
	{
		public final int itemId;
		public final String itemName;
		public final int targetSlot;
		public final String instruction;
		public final String subCategory;
		public final int targetItemId;
		public final String phaseDescription;
		public final int totalOutOfPlace;

		public OrderStep(int itemId, String itemName, int targetSlot, String instruction,
			String subCategory, int targetItemId, String phaseDescription, int totalOutOfPlace)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.targetSlot = targetSlot;
			this.instruction = instruction;
			this.subCategory = subCategory;
			this.targetItemId = targetItemId;
			this.phaseDescription = phaseDescription;
			this.totalOutOfPlace = totalOutOfPlace;
		}
	}

	public static class PreviewItem
	{
		public final int itemId;
		public final String name;
		public final String subCategory;
		public final int position; // ideal position index

		public PreviewItem(int itemId, String name, String subCategory, int position)
		{
			this.itemId = itemId;
			this.name = name;
			this.subCategory = subCategory;
			this.position = position;
		}
	}
}

package com.bankorganizer;

import java.util.HashMap;
import java.util.ArrayList;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Manages profile storage, switching, import/export.
 * Profiles are stored in RuneLite config as Base64-encoded strings.
 */
public class ProfileManager
{
	private static final Logger log = LoggerFactory.getLogger(ProfileManager.class);

	private final BankOrganizerConfig config;
	private final Map<String, BankOrganizerProfile> profiles = new LinkedHashMap<>();
	private String activeProfileName;

	public ProfileManager(BankOrganizerConfig config)
	{
		this.config = config;
	}

	public void loadProfiles()
	{
		profiles.clear();

		String profileListStr = config.profileList();
		if (profileListStr == null || profileListStr.isEmpty())
		{
			profileListStr = "Default Layout";
		}

		String[] names = profileListStr.split("\\|");
		String dataStr = config.profileData();
		Map<String, String> dataMap = new LinkedHashMap<>();

		if (dataStr != null && !dataStr.isEmpty())
		{
			// Format: name1::base64data1||name2::base64data2
			for (String block : dataStr.split("\\|\\|"))
			{
				int sep = block.indexOf("::");
				if (sep > 0)
				{
					dataMap.put(block.substring(0, sep), block.substring(sep + 2));
				}
			}
		}

		for (String name : names)
		{
			name = name.trim();
			if (name.isEmpty()) continue;

			String encoded = dataMap.get(name);
			if (encoded != null)
			{
				try
				{
					String decoded = new String(Base64.getDecoder().decode(encoded));
					BankOrganizerProfile profile = BankOrganizerProfile.deserialize(decoded);
					if (profile != null)
					{
						profiles.put(name, profile);
						continue;
					}
				}
				catch (Exception e)
				{
					log.warn("Failed to decode profile: {}", name, e);
				}
			}

			// Create empty profile if data not found
			profiles.put(name, new BankOrganizerProfile(name));
		}

		// Ensure at least "Default Layout" exists
		if (!profiles.containsKey("Default Layout"))
		{
			profiles.put("Default Layout", BankOrganizerProfile.createDefault());
		}

		activeProfileName = config.activeProfile();
		if (activeProfileName == null || !profiles.containsKey(activeProfileName))
		{
			activeProfileName = "Default Layout";
		}

		log.info("Loaded {} profiles, active: {}", profiles.size(), activeProfileName);
	}

	public void saveProfiles()
	{
		StringBuilder nameList = new StringBuilder();
		StringBuilder dataList = new StringBuilder();

		for (Map.Entry<String, BankOrganizerProfile> entry : profiles.entrySet())
		{
			if (nameList.length() > 0) nameList.append("|");
			nameList.append(entry.getKey());

			if (dataList.length() > 0) dataList.append("||");
			String serialized = entry.getValue().serialize();
			String encoded = Base64.getEncoder().encodeToString(serialized.getBytes());
			dataList.append(entry.getKey()).append("::").append(encoded);
		}

		config.setProfileList(nameList.toString());
		config.setProfileData(dataList.toString());
		config.setActiveProfile(activeProfileName);
	}

	public BankOrganizerProfile getActiveProfile()
	{
		return profiles.getOrDefault(activeProfileName,
			BankOrganizerProfile.createDefault());
	}

	public String getActiveProfileName()
	{
		return activeProfileName;
	}

	public List<String> getProfileNames()
	{
		return new ArrayList<>(profiles.keySet());
	}

	/**
	 * Switch to a different profile. Returns the profile.
	 */
	public BankOrganizerProfile switchProfile(String name)
	{
		if (!profiles.containsKey(name))
		{
			log.warn("Profile not found: {}", name);
			return getActiveProfile();
		}

		activeProfileName = name;
		saveProfiles();
		log.info("Switched to profile: {}", name);
		return profiles.get(name);
	}

	/**
	 * Save current state to the active profile.
	 */
	public void saveCurrentState(String catOverrides, String subOverrides)
	{
		saveCurrentState(catOverrides, subOverrides, null);
	}

	public void saveCurrentState(String catOverrides, String subOverrides, java.util.Collection<Integer> userItems)
	{
		BankOrganizerProfile profile = getActiveProfile();
		profile.setCategoryOverrides(catOverrides);
		profile.setSubCategoryOverrides(subOverrides);
		if (userItems != null) profile.setUserItems(userItems);
		saveProfiles();
	}

	/** Result of merging shipped defaults with a profile's own overrides. */
	public static final class MergeResult
	{
		public final Map<Integer, ItemCategory> categories;
		public final Map<Integer, Integer> subCategories;
		public final java.util.Set<Integer> userItems;

		MergeResult(Map<Integer, ItemCategory> c, Map<Integer, Integer> s, java.util.Set<Integer> u)
		{
			categories = c; subCategories = s; userItems = u;
		}
	}

	/**
	 * Shipped defaults + the user's own overrides on top. For {@code userItems} the current state wins
	 * (including "no override" if the user cleared one). When {@code legacy} is true there is no record of
	 * what the user touched, so every current override that differs from the shipped value is treated as
	 * user-made and recorded.
	 */
	public static MergeResult mergeDefaults(Map<Integer, ItemCategory> shippedCat, Map<Integer, Integer> shippedSub,
		Map<Integer, ItemCategory> curCat, Map<Integer, Integer> curSub,
		java.util.Set<Integer> userItems, boolean legacy)
	{
		java.util.Set<Integer> user = new java.util.LinkedHashSet<>(userItems);
		if (legacy)
		{
			for (Map.Entry<Integer, ItemCategory> e : curCat.entrySet())
			{
				if (e.getValue() != shippedCat.get(e.getKey())) user.add(e.getKey());
			}
			for (Map.Entry<Integer, Integer> e : curSub.entrySet())
			{
				if (!e.getValue().equals(shippedSub.get(e.getKey()))) user.add(e.getKey());
			}
		}
		Map<Integer, ItemCategory> mergedCat = new HashMap<>(shippedCat);
		Map<Integer, Integer> mergedSub = new HashMap<>(shippedSub);
		for (Integer id : user)
		{
			ItemCategory c = curCat.get(id);
			if (c != null) mergedCat.put(id, c); else mergedCat.remove(id);
			Integer sub = curSub.get(id);
			if (sub != null) mergedSub.put(id, sub); else mergedSub.remove(id);
		}
		return new MergeResult(mergedCat, mergedSub, user);
	}

	public String readDefaultResource(String name)
	{
		try (java.io.InputStream is = getClass().getResourceAsStream("/com/bankorganizer/" + name))
		{
			return is == null ? "" : new String(is.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).trim();
		}
		catch (Exception e)
		{
			log.warn("Failed to read {}", name, e);
			return "";
		}
	}

	/**
	 * Create a new profile from defaults.
	 */
	public BankOrganizerProfile createFromDefault(String name)
	{
		BankOrganizerProfile profile = BankOrganizerProfile.createDefault();
		profile.setName(name);
		profile.setDefaultsVersion(BankOrganizerPlugin.VERSION);

		// Copy default overrides from resource files
		try
		{
			java.io.InputStream catStream = getClass().getResourceAsStream("/com/bankorganizer/default_overrides.txt");
			if (catStream != null)
			{
				profile.setCategoryOverrides(new String(catStream.readAllBytes()).trim());
				catStream.close();
			}
			java.io.InputStream subStream = getClass().getResourceAsStream("/com/bankorganizer/default_sub_overrides.txt");
			if (subStream != null)
			{
				profile.setSubCategoryOverrides(new String(subStream.readAllBytes()).trim());
				subStream.close();
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load default overrides for new profile", e);
		}

		profiles.put(name, profile);
		saveProfiles();
		log.info("Created profile from defaults: {}", name);
		return profile;
	}

	/**
	 * Create a blank profile with no overrides.
	 */
	public BankOrganizerProfile createBlank(String name)
	{
		BankOrganizerProfile profile = BankOrganizerProfile.createBlank(name);
		profiles.put(name, profile);
		saveProfiles();
		log.info("Created blank profile: {}", name);
		return profile;
	}

	/**
	 * Delete a profile.
	 */
	public boolean deleteProfile(String name)
	{
		if ("Default Layout".equals(name))
		{
			return false; // Can't delete default
		}

		profiles.remove(name);
		if (activeProfileName.equals(name))
		{
			activeProfileName = "Default Layout";
		}
		saveProfiles();
		log.info("Deleted profile: {}", name);
		return true;
	}

	/**
	 * Export active profile as a shareable string (Base64).
	 */
	public String exportProfile()
	{
		BankOrganizerProfile profile = getActiveProfile();
		String serialized = profile.serialize();
		return Base64.getEncoder().encodeToString(serialized.getBytes());
	}

	/**
	 * Import a profile from Base64 string.
	 */
	public BankOrganizerProfile importProfile(String encoded)
	{
		try
		{
			String decoded = new String(Base64.getDecoder().decode(encoded.trim()));
			BankOrganizerProfile profile = BankOrganizerProfile.deserialize(decoded);
			if (profile == null)
			{
				return null;
			}

			// Avoid name collision
			String name = profile.getName();
			int i = 1;
			while (profiles.containsKey(name))
			{
				name = profile.getName() + " (" + i + ")";
				i++;
			}
			profile.setName(name);

			profiles.put(name, profile);
			saveProfiles();
			log.info("Imported profile: {}", name);
			return profile;
		}
		catch (Exception e)
		{
			log.error("Failed to import profile", e);
			return null;
		}
	}
}

